#!/usr/bin/env python3
"""Embed the web terminal assets (xterm.js, fit addon, css) gzip-compressed
into src/web_assets.h, so the terminal page works without internet.

usage: tools/embed_web.py web-vendor src/web_assets.h
(web-vendor holds the unpacked npm packages xterm 5.3.0 and
xterm-addon-fit 0.8.0, checked against the registry's sha512 integrity)
"""
import gzip
import os
import sys

FILES = [  # (url path, file in the vendor dir, content type, C name)
    ("/xterm.js", "xterm/lib/xterm.js", "application/javascript", "XTERM_JS"),
    ("/xterm-addon-fit.js", "xterm-addon-fit/lib/xterm-addon-fit.js",
     "application/javascript", "XTERM_FIT_JS"),
    ("/xterm.css", "xterm/css/xterm.css", "text/css", "XTERM_CSS"),
    ("/favicon.png", "../web/favicon-64.png", "image/png", "FAVICON_PNG"),
    ("/logo.webp", "../web/logo-96.webp", "image/webp", "LOGO_WEBP"),
]


def main():
    vendor, out = sys.argv[1], sys.argv[2]
    lic = open(os.path.join(vendor, "xterm/LICENSE")).read()
    lines = ["#pragma once", "/* generated by tools/embed_web.py - do not edit",
             " * xterm.js 5.3.0 and xterm-addon-fit 0.8.0, MIT license:", " *"]
    lines += [(" * " + ln).rstrip() for ln in lic.replace("*/", "* /").splitlines()]
    lines += [" */", "#include <stddef.h>", "#include <stdint.h>", ""]
    table = []
    total = 0
    for url, path, ctype, name in FILES:
        raw = open(os.path.join(vendor, path), "rb").read()
        # strip the source map reference, the map is not served
        raw = b"\n".join(ln for ln in raw.split(b"\n")
                         if not ln.startswith(b"//# sourceMappingURL="))
        gz = gzip.compress(raw, 9, mtime=0)
        total += len(gz)
        lines.append("static const uint8_t %s[] PROGMEM = {" % name)
        for i in range(0, len(gz), 20):
            lines.append("\t" + ",".join("%d" % b for b in gz[i:i + 20]) + ",")
        lines.append("};")
        table.append('\t{ "%s", "%s", %s, sizeof(%s) },' % (url, ctype, name, name))
        print("%-22s %7d -> %6d bytes gz" % (url, len(raw), len(gz)))
    lines += ["", "struct WebAsset {", "\tconst char *path, *type;",
              "\tconst uint8_t *data;", "\tsize_t len;", "};",
              "static const WebAsset WEB_ASSETS[] = {"] + table + ["};", ""]
    open(out, "w").write("\n".join(lines))
    print("total %d bytes" % total)


if __name__ == "__main__":
    main()
